async function CompleteGenericSendMessage(msgType) {
  // hook for extra compose pre-processing
  Services.obs.notifyObservers(window, "mail:composeOnSend");

  gAutoSaving = msgType == Ci.nsIMsgCompDeliverMode.AutoSaveAsDraft;
  if (gAutoSaving && gAutoSavingInProgress) {
    return;
  }
  try {
    if (gAutoSaving) {
      gAutoSavingInProgress = true;
    }

    if (!gSelectedTechnologyIsPGP) {
      gMsgCompose.compFields.composeSecure.requireEncryptMessage =
        gSendEncrypted;
      gMsgCompose.compFields.composeSecure.signMessage = gSendSigned;
      onSendSMIME();
    }

    if (gSelectedTechnologyIsPGP) {
      if (!(await Enigmail.msg.onSendOpenPGP(msgType))) {
        Enigmail.msg.resetUpdatedFields();
        return;
      }
    }

    if (gSelectedTechnologyIsPGP || !(gSendSigned || gSendEncrypted)) {
      const senderKeyId =
        gCurrentIdentity.getUnicharAttribute("openpgp_key_id");
      if (gCurrentIdentity.sendAutocryptHeaders && senderKeyId) {
        const fromMail =
          EnigmailFuncs.stripEmail(gMsgCompose.compFields.from) ||
          gCurrentIdentity.email;
        let keyData = EnigmailKeyRing.getAutocryptKey(
          "0x" + senderKeyId,
          fromMail
        );
        if (keyData) {
          keyData =
            " " + keyData.replace(/(.{72})/g, "$1\r\n ").replace(/\r\n $/, "");
          gMsgCompose.compFields.setHeader(
            "Autocrypt",
            "addr=" + fromMail + "; keydata=\r\n" + keyData
          );
        }
      }
    }

    // Just before we try to send the message, fire off the
    // compose-send-message event for listeners.
    const event = new CustomEvent("compose-send-message", {
      cancelable: true,
      detail: { msgType },
    });
    window.dispatchEvent(event);
    if (event.defaultPrevented) {
      throw Components.Exception(
        "compose-send-message prevented",
        Cr.NS_ERROR_ABORT
      );
    }

    // disable the ui if we're not auto-saving
    if (!gAutoSaving) {
      ToggleWindowLock(true);
    } else {
      // If we're auto saving, mark the body as not changed here, and not
      // when the save is done, because the user might change it between now
      // and when the save is done.
      SetContentAndBodyAsUnmodified();
    }

    // Keep track of send/saved cloudFiles and mark them as immutable.
    const items = [...gAttachmentBucket.itemChildren];
    for (const item of items) {
      if (item.attachment.sendViaCloud && item.cloudFileAccount) {
        item.cloudFileAccount.markAsImmutable(item.cloudFileUpload.id);
      }
    }

    var progress = Cc["@mozilla.org/messenger/progress;1"].createInstance(
      Ci.nsIMsgProgress
    );
    if (progress) {
      progress.registerListener(progressListener);
      if (
        msgType == Ci.nsIMsgCompDeliverMode.Save ||
        msgType == Ci.nsIMsgCompDeliverMode.SaveAsDraft ||
        msgType == Ci.nsIMsgCompDeliverMode.AutoSaveAsDraft ||
        msgType == Ci.nsIMsgCompDeliverMode.SaveAsTemplate
      ) {
        gSaveOperationInProgress = true;
      } else {
        gSendOperationInProgress = true;
      }
    }
    window.browsingContext.docShell.allowAuth = true;
    progress.msgWindow = msgWindow;
    await gMsgCompose.sendMsg(
      msgType,
      gCurrentIdentity,
      getCurrentAccountKey(),
      progress
    );
  } catch (ex) {
    ToggleWindowLock(false);
    if (ex?.result == Cr.NS_ERROR_ABORT) {
      // The user cancelled the send; this is not an error.
      return;
    }
    console.warn(`GenericSendMessage FAILED: ${ex.message}`, ex);
    return;
  } finally {
    if (gAutoSaving) {
      gAutoSavingInProgress = false;
    }
  }
